define('mathEntryInteraction/runtime/helper/mathInPrompt',['mathEntryInteraction/runtime/mathml-to-latex/mathml-to-latex', 'mathEntryInteraction/runtime/mathquill/mathquill'], function (Mathml2latex, MathQuill) {
  'use strict';

  var MQ = MathQuill.getInterface(2);
  if (Mathml2latex.MathMLToLaTeX) {
    Mathml2latex = Mathml2latex.MathMLToLaTeX;
  }
  function getLaTeX(element) {
    var annotation = element.querySelector('annotation');
    if (annotation) {
      return annotation.innerHTML;
    }
    return Mathml2latex.convert(element.outerHTML);
  }
  var mathInPrompt = {
    postRender($element) {
      var $mathElements = $element.find('math');
      if (!$mathElements.length) {
        return;
      }
      if (window.MathJax && window.MathJax.Hub) {
        window.MathJax.Hub.Queue(['Typeset', window.MathJax.Hub, $element[0]]);
        return;
      }
      $mathElements.each(function () {
        var math = document.createElement('span');
        math.innerHTML = getLaTeX(this);
        this.replaceWith(math);
        MQ.StaticMath(math);
      });
    }
  };
  return mathInPrompt;
});
