define('mathEntryInteraction/runtime/helper/ambiguousSymbols',[], function () {
  'use strict';
  var defaultMapping = {
    '０': '0',
    '１': '1',
    '２': '2',
    '３': '3',
    '４': '4',
    '５': '5',
    '６': '6',
    '７': '7',
    '８': '8',
    '９': '9',
    '−': '-',
    '‐': '-',
    '―': '-',
    '-': '-'
  };
  function convert(text) {
    var result = '';
    for (var char of text) {
      result += defaultMapping[char] || char;
    }
    return result;
  }
  return convert;
});
